class Solution {
    public int longestSubarray(int[] nums, int k) {
       // two pointer
       // idea is to solve this problem in linear time
       //o(n), 
       //o increase the sum of the elements in window, we can expand the window by one element.
        //To decrease the sum of the elements in window, we can shrink the window by one element.
        int n = nums.length;
        int maxLen = 0;
        int l = 0 , r = 0;
        int sum = nums[0];
        while(r<n){
            while(l<=r && sum > k){
                sum -=nums[l];
                l++;
            }
            if(sum == k){
                maxLen = Math.max(maxLen , r-l+1);
            }
            r ++ ;
            if(r<n) sum +=nums[r];
        }
        return maxLen;
    }
}
```

